(n, k) = list(map(int, input().split()))
arr = list(map(int, input().split()))
s = 1
max_num = arr[0]
prev = -1
index_map = {}
index_map[arr[0]] = 0
for i in range(1, n):
	if arr[i] <= k:
		s += i - prev
	else:
		for j in range(max_num // arr[i] + 1):
			if arr[i] * j + k in index_map:
				prev = max(prev, index_map[arr[i] * j + k])
		s += i - prev
	index_map[arr[i]] = i
	max_num = max(max_num, arr[i])
print(s)
